import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"What Is AL and Why Does Business Central Use It?","description":"","frontmatter":{},"headers":[],"relativePath":"your-first-al-programs/what-is-al.md","filePath":"your-first-al-programs/what-is-al.md"}`),a={name:`your-first-al-programs/what-is-al.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="what-is-al-and-why-does-business-central-use-it" tabindex="-1">What Is AL and Why Does Business Central Use It? <a class="header-anchor" href="#what-is-al-and-why-does-business-central-use-it" aria-label="Permalink to “What Is AL and Why Does Business Central Use It?”">​</a></h1><h2 id="what-is-al" tabindex="-1">What Is AL? <a class="header-anchor" href="#what-is-al" aria-label="Permalink to “What Is AL?”">​</a></h2><p><strong>AL (Application Language)</strong> is the programming language used to develop and customize applications for Microsoft Dynamics 365 Business Central.</p><p>It allows developers to add business functionality, extend existing features, and integrate Business Central with external systems.</p><p>For example, using AL, you can:</p><ul><li>Create tables to store business data.</li><li>Build pages for displaying and editing records.</li><li>Implement business rules, validations, and calculations.</li><li>Automate business processes.</li><li>Integrate Business Central with external APIs.</li></ul><p><strong>Think of it this way:</strong> Business Central is the business application, while AL is the language you use to extend its capabilities.</p><p>AL is designed for business applications, particularly those involving financial management, inventory, sales, purchasing, and other ERP processes.</p><h2 id="why-does-business-central-use-al" tabindex="-1">Why Does Business Central Use AL? <a class="header-anchor" href="#why-does-business-central-use-al" aria-label="Permalink to “Why Does Business Central Use AL?”">​</a></h2><p>Business Central already provides functionality for managing finances, inventory, customers, suppliers, and more. However, different businesses have different requirements.</p><p>For example, one company might need a custom approval process before a purchase order can be submitted. Another might need to integrate Business Central with its own e-commerce platform.</p><p>AL allows developers to implement these requirements without building an entirely new ERP system.</p><p>Key benefits include:</p><ul><li><strong>Customization:</strong> Add functionality to meet specific business requirements.</li><li><strong>Extensibility:</strong> Extend standard Business Central functionality without directly modifying Microsoft&#39;s base application.</li><li><strong>Business logic:</strong> Implement rules, validations, calculations, and workflows.</li><li><strong>Integration:</strong> Connect Business Central to external applications and services.</li><li><strong>Maintainability:</strong> Package custom functionality separately from the standard application using extensions.</li></ul>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};